CREATE TABLE IF NOT EXISTS stock_items (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT, name TEXT NOT NULL, description TEXT, category TEXT, mode TEXT NOT NULL DEFAULT 'batch', unit TEXT NOT NULL DEFAULT 'each', weight TEXT NOT NULL DEFAULT 'light', usual_location INTEGER, supplier TEXT, supplier_part TEXT, manufacturer TEXT, mpn TEXT, unit_cost REAL, lead_days INTEGER, two_bin INTEGER NOT NULL DEFAULT 0, reorder_qty REAL, min_qty REAL, shelf_life_days INTEGER, active INTEGER NOT NULL DEFAULT 1, created_at TEXT, created_by TEXT);
CREATE TABLE IF NOT EXISTS stock_aliases (code TEXT PRIMARY KEY, item_id INTEGER NOT NULL, kind TEXT);
CREATE INDEX IF NOT EXISTS idx_stock_aliases_item ON stock_aliases(item_id);
CREATE TABLE IF NOT EXISTS stock_locations (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, area TEXT, name TEXT, level TEXT NOT NULL DEFAULT 'mid', quarantine INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS stock_units (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT, item_id INTEGER NOT NULL, lot TEXT, serial TEXT, qty REAL NOT NULL, location_id INTEGER, status TEXT NOT NULL DEFAULT 'available', order_id INTEGER, team TEXT, received_at TEXT, received_by TEXT, expiry TEXT, supplier TEXT, po_ref TEXT, po_date TEXT, unit_cost REAL, expected_id INTEGER, picked_at TEXT, picked_by TEXT, consumed_at TEXT, note TEXT);
CREATE INDEX IF NOT EXISTS idx_stock_units_item ON stock_units(item_id, status);
CREATE INDEX IF NOT EXISTS idx_stock_units_order ON stock_units(order_id, status);
CREATE INDEX IF NOT EXISTS idx_stock_units_code ON stock_units(code);
CREATE INDEX IF NOT EXISTS idx_stock_units_location ON stock_units(location_id);
CREATE TABLE IF NOT EXISTS stock_expected (id INTEGER PRIMARY KEY AUTOINCREMENT, item_id INTEGER NOT NULL, qty REAL NOT NULL, received_qty REAL NOT NULL DEFAULT 0, issue_qty REAL NOT NULL DEFAULT 0, issue_note TEXT, supplier TEXT, po_ref TEXT, po_date TEXT, expected_date TEXT, team TEXT, order_id INTEGER, unit_cost REAL, status TEXT NOT NULL DEFAULT 'open', note TEXT, created_at TEXT, created_by TEXT);
CREATE INDEX IF NOT EXISTS idx_stock_expected_item ON stock_expected(item_id, status);
CREATE TABLE IF NOT EXISTS stock_orders (id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL DEFAULT 'job', key TEXT NOT NULL UNIQUE, epic_key TEXT, summary TEXT, order_summary TEXT, customer TEXT, team TEXT, start_date TEXT, end_date TEXT, needed_by TEXT, priority_auto TEXT, priority_override TEXT, priority_by TEXT, status TEXT NOT NULL DEFAULT 'open', jira_done INTEGER NOT NULL DEFAULT 0, subtasks TEXT, po_key TEXT, po_text TEXT, imported INTEGER NOT NULL DEFAULT 0, note TEXT, completed_at TEXT, completed_by TEXT, created_at TEXT, created_by TEXT, seen_at TEXT);
CREATE TABLE IF NOT EXISTS stock_needs (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL, item_id INTEGER, text TEXT, qty REAL NOT NULL DEFAULT 1, source TEXT, created_at TEXT, created_by TEXT);
CREATE INDEX IF NOT EXISTS idx_stock_needs_order ON stock_needs(order_id);
CREATE TABLE IF NOT EXISTS stock_moves (id INTEGER PRIMARY KEY AUTOINCREMENT, at TEXT NOT NULL, account_id TEXT, name TEXT, action TEXT NOT NULL, item_id INTEGER, unit_id INTEGER, unit_code TEXT, lot TEXT, qty REAL, from_location INTEGER, to_location INTEGER, order_id INTEGER, order_key TEXT, from_status TEXT, to_status TEXT, note TEXT);
CREATE INDEX IF NOT EXISTS idx_stock_moves_unit ON stock_moves(unit_id);
CREATE INDEX IF NOT EXISTS idx_stock_moves_item ON stock_moves(item_id, at);
CREATE INDEX IF NOT EXISTS idx_stock_moves_order ON stock_moves(order_id);
CREATE INDEX IF NOT EXISTS idx_stock_moves_who ON stock_moves(account_id, at);
CREATE TABLE IF NOT EXISTS stock_panels (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, notes TEXT, updated_at TEXT, updated_by TEXT);
CREATE TABLE IF NOT EXISTS stock_panel_items (panel_id INTEGER NOT NULL, item_id INTEGER NOT NULL, qty REAL NOT NULL, PRIMARY KEY (panel_id, item_id));
CREATE TABLE IF NOT EXISTS stock_plans (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, areas TEXT, every_days INTEGER NOT NULL DEFAULT 30, next_due TEXT, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS stock_checks (id INTEGER PRIMARY KEY AUTOINCREMENT, plan_id INTEGER, name TEXT, areas TEXT, status TEXT NOT NULL DEFAULT 'open', started_at TEXT, started_by TEXT, finished_at TEXT, applied_at TEXT, applied_by TEXT);
CREATE TABLE IF NOT EXISTS stock_check_locations (check_id INTEGER NOT NULL, location_id INTEGER NOT NULL, done_by TEXT, done_at TEXT, PRIMARY KEY (check_id, location_id));
CREATE TABLE IF NOT EXISTS stock_counts (check_id INTEGER NOT NULL, location_id INTEGER NOT NULL, item_id INTEGER NOT NULL, expected REAL, counted REAL, counted_by TEXT, counted_at TEXT, PRIMARY KEY (check_id, location_id, item_id));
CREATE TABLE IF NOT EXISTS stock_time_hidden (account_id TEXT NOT NULL, order_key TEXT NOT NULL, day TEXT NOT NULL, PRIMARY KEY (account_id, order_key, day));
